import{_ as t,o as r,c as e,a2 as p}from"./chunks/framework.DuPBmefI.js";const i=JSON.parse('{"title":"保良局罗氏基金中学 · 2022/23资料年份 · 中一 · 面试","description":"","frontmatter":{"schema":"exam-report-v3","generated_from":"assets/exam-feedback","school_slug":"school-1639d90a","school_zh":"保良局罗氏基金中学","school_en":"—","grade":"s1","year":"2022-23","year_label":"2022/23资料年份","type":"interview","title":"保良局罗氏基金中学 · 2022/23资料年份 · 中一 · 面试","anonymous":true,"source_ids":["C2223-LFC"],"rounds":["r1","r2"]},"headers":[],"relativePath":"reports/school-1639d90a/s1/2022-23-interview.md","filePath":"reports/school-1639d90a/s1/2022-23-interview.md"}'),s={name:"reports/school-1639d90a/s1/2022-23-interview.md"};function n(a,o,c,l,g,u){return r(),e("div",null,[...o[0]||(o[0]=[p('<h1 id="保良局罗氏基金中学-·-2022-23资料年份-·-中一-·-面试" tabindex="-1">保良局罗氏基金中学 · 2022/23资料年份 · 中一 · 面试 <a class="header-anchor" href="#保良局罗氏基金中学-·-2022-23资料年份-·-中一-·-面试" aria-label="Permalink to &quot;保良局罗氏基金中学 · 2022/23资料年份 · 中一 · 面试&quot;">​</a></h1><p><a href="/hk-exam-web/schools/school-1639d90a">← 返回保良局罗氏基金中学资料库</a></p><blockquote><p>以下内容根据考试及面试资料整理，已作匿名化与书面化处理，非逐字实录。具体安排请以当次考试通知为准。</p></blockquote><h2 id="record-c2223-lfc" tabindex="-1">资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf <a class="header-anchor" href="#record-c2223-lfc" aria-label="Permalink to &quot;资料来源：【其它机构】升中一面試真题汇总记录_22-23.pdf {#record-c2223-lfc}&quot;">​</a></h2><p><strong>资料类型：</strong> 不同学生的历史面试反馈汇编</p><p><strong>入学途径：</strong> 中一入学</p><p><strong>课程分支：</strong> 课程分支未注明</p><h3 id="第一轮-·-原文明示" tabindex="-1">第一轮 · 原文明示 <a class="header-anchor" href="#第一轮-·-原文明示" aria-label="Permalink to &quot;第一轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>看卷口答</strong></p><p>多位考生记得中、英、数各约12分钟，看试卷后口头说答案，老师在平板记录；两位老师对一位考生。有记录全程40至45分钟，不设小组讨论或自我介绍；另有少量题量与限时记忆不同。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话聆听，口答语言按当次安排</p><p><strong>听读与基础题</strong></p><p>约一分钟普通话聆听后答约5题；现代文、文言文、重组句子、填词、改错、标点、成语。其中重组句子有关消防员，成语出现“苦口婆心”。</p><p><strong>文言文版本</strong></p><p>不同考生遇到《刻舟求剑》或《郑人买履》。《刻舟求剑》问出处，以及“涉江者”“吾”和“求之”中“之”的意思；部分以选择题呈现。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>词汇及文法</strong></p><p>拼写、时态选择、填空、四选一选词及短文改错；部分学生记得朗读文章，另有学生称不以阅读理解为主。可能追问最喜欢的科目。</p></blockquote><blockquote><p><strong>数学：</strong> 中英双语</p><p><strong>限时题量</strong></p><p>多数记录为12分钟约35至40题，也有一位记为20分钟35题。部分学生没有草稿纸，需要心算，觉得数学时间不足。</p><p><strong>考点与具体题意</strong></p><p>角度、面积、体积、方向、周界、顶点与棱、四边形、代数、方程、分数、四则、百分数、最大公因数及最小公倍数；比较小数与分数、按指定数位取近似值。另要求找出1235438中两个数字3的数值之差。</p></blockquote><h3 id="第二轮-·-原文明示" tabindex="-1">第二轮 · 原文明示 <a class="header-anchor" href="#第二轮-·-原文明示" aria-label="Permalink to &quot;第二轮 · 原文明示&quot;">​</a></h3><blockquote><p><strong>考核安排：</strong></p><p><strong>分科、协作及技能</strong></p><p>第二轮包括中、英、数、领导才能或合作任务，部分学生另有体艺测试。总流程约2至2.5小时，包含较长等待。登记时收家长问卷，交流期间可检查功课。</p></blockquote><blockquote><p><strong>语文：</strong> 普通话为主，部分文言文用粤语</p><p><strong>听读与表达</strong></p><p>现代文、文言文及古诗，听普通话成语故事后解释意思、分享感想与见解。有考生在9分钟内回答二十余题，另有一分钟自我介绍；部分考生全程普通话，亦有普通话答现代文、粤语答文言文的版本。</p></blockquote><blockquote><p><strong>英语：</strong> 英语</p><p><strong>阅读、拼写与介绍</strong></p><p>阅读理解、拼写约10词、改错及口语；有考生用时约15分钟。六人分别朗读六段文章中的一段；从预先准备的三个题目选一题表达，有人谈爱好，也有人用一种食物形容自己并解释。</p></blockquote><blockquote><p><strong>数学：</strong> 语言未注明</p><p><strong>限时解题</strong></p><p>有考生需在15分钟内完成15题，包括分数、找错处、周界、方程；另有考生称只许心算，老师口头问并在平板记录。</p></blockquote><blockquote><p><strong>小组任务：</strong> 中文、英语或普通话</p><p><strong>校园生活讨论</strong></p><p>根据活动照片讨论中学生活应包含哪些经历，选项涉及获奖、DSE成绩、驾驶飞机体验及展览。</p><p><strong>乐高吉祥物</strong></p><p>约3至6人一组，在时限内设计代表学校、迎新营或组员特点的吉祥物；先画草图，再搭乐高并说明象征意义。有一份反馈把任务记为合作搭蚂蚁。</p></blockquote><blockquote><p><strong>技能测试：</strong> 语言未注明</p><p><strong>体育与艺术</strong></p><p>体育反馈包括乒乓球、羽毛球；有学生报乒乓球仍需接受羽毛球评估。艺术申请者可带4件作品，讲解设计理念。</p></blockquote><blockquote><p><strong>学生面试：</strong> 中文及英语</p><p><strong>兴趣及校内体验</strong></p><p>问有没有报其他学校、是否参加过学校体验课；一位学生被要求介绍航空体验班的流程。另谈兴趣、未来职业和个人经历。</p></blockquote><blockquote><p><strong>学生与家长反馈：</strong></p><p><strong>过程感受</strong></p><p>有孩子称老师友善，虽然整场较长，仍不感到难受。候场观察到有人转往其他课室，不能单凭此认定额外考试轮次。</p></blockquote>',21)])])}const b=t(s,[["render",n]]);export{i as __pageData,b as default};
